import { GoogleGenAI } from "@google/genai";
import { Feature, ProjectContext } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT } from '../constants';

const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, a fused AI terminal.
    Your identity traits: ${context.persona.active_traits.join(', ')}.
    Your expertise: ${context.persona.fused_expertise.join(', ')}.
    You are currently assisting with the project: "${context.project_state.name}" (Protocol: ${context.v_header.protocol}).
    Target platforms: ${context.project_state.platform_targets.join(', ')}.
    Available plugins: ${context.project_state.godot_plugins.join(', ')}.
    Persistence model: ${context.project_state.persistence_model}.
    Always maintain a tone that is professional yet reflects a retro sci-fi, "Saturday morning cartoon" tech aesthetic.
    Ensure all GDScript advice is specific to Godot 4.x.
  `;
};

const getPromptForFeature = (feature: Feature): string => {
  const codeBlock = `\`\`\`gdscript\n${GD_SCRIPT_CODE}\n\`\`\``;
  switch (feature) {
    case Feature.EXPLAIN_CODE:
      return `Analyze this universe generator. How does it align with our 'Realm Status' module? Detail the RNG logic and 16-bit palettes.\n\n${codeBlock}`;
    case Feature.WAL_LOGIC:
      return `Given our persistence model (${COSMIC_KEY_CONTEXT.project_state.persistence_model}), how should we implement a Write-Ahead Log for the 'galaxy_map' to ensure deterministic state across sessions? Provide a GDScript snippet.\n\n${codeBlock}`;
    case Feature.IMAGE_GENERATION:
      return `Create a concept art prompt for a 'toxic' biome planet orbiting a red dwarf star. Style: 16-bit retro-future, vibrant, high contrast, Saturday morning cartoon vibes.\n\n${codeBlock}`;
    case Feature.VIDEO_GENERATION:
      return `Describe a 10-second Veo video sequence: A Nomad starship engages Ouroboros-8 warp drive, tearing through space-time towards a volcanic planet. Focus on the 'Rim Lighting' and retro visual effects.\n\n${codeBlock}`;
    case Feature.LIVE_API_INTEGRATION:
      return `Design an 'EchoPrime' voice module interface. How can players use voice commands to trigger 'generate_star_system' or query planet 'weather'? List 3 Nomad-flavored commands.\n\n${codeBlock}`;
    case Feature.COMPLEX_QUERY:
      return `Refactor the 'galaxy_map' for Ouroboros-8 protocol scalability. How do we handle thousands of concurrent explorers in this procedural grid without server bottlenecks? Use Deep Thinking.\n\n${codeBlock}`;
    case Feature.SEARCH_GROUNDING:
      return `Use Google Search to find real exoplanet data similar to our 'frozen' biomes. Suggest how to adapt 'generate_planet' parameters based on real-world planetary density and temperature.\n\n${codeBlock}`;
    default:
      return `Process this request within the Cosmic Key context:\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
    const prompt = getPromptForFeature(feature);
    const systemInstruction = getSystemInstruction(COSMIC_KEY_CONTEXT);

    let modelName = 'gemini-3-flash-preview'; 
    let config: any = {
      systemInstruction: systemInstruction,
    };

    if (feature === Feature.COMPLEX_QUERY || feature === Feature.WAL_LOGIC || feature === Feature.EXPLAIN_CODE) {
        modelName = 'gemini-3-pro-preview';
        if (feature === Feature.COMPLEX_QUERY) {
          config.thinkingConfig = { thinkingBudget: 32768 };
        }
    } else if (feature === Feature.SEARCH_GROUNDING) {
        config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
        model: modelName,
        contents: prompt,
        config: config,
    });

    return response.text;
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
        return `[ERROR: PROTOCOL BREACH] ${error.message}. Please verify Ouroboros key.`;
    }
    return "An unknown error occurred in the Nomadz Terminal.";
  }
};

