import React, { useState, useCallback } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT } from './constants';
import { Feature } from './types';
import { generateContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.EXPLAIN_CODE);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = useCallback(async () => {
    setIsLoading(true);
    setOutput('');
    setError(null);
    const result = await generateContent(selectedFeature);
    setOutput(result);
    setIsLoading(false);
  }, [selectedFeature]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);

  return (
    <div className="min-h-screen p-4 sm:p-6 lg:p-8 bg-[#0a0f0d] text-teal-100 font-mono relative overflow-hidden">
      {/* Background scanline effect */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_2px,3px_100%] z-50"></div>

      <header className="mb-8 flex flex-col md:flex-row items-center justify-between border-b-2 border-teal-900 pb-4">
        <div>
          <h1 className="text-3xl font-black text-teal-400 italic tracking-tighter">
            COSMIC KEY <span className="text-teal-800 text-xl font-normal">NOMADZ_TERM_0.0.1</span>
          </h1>
          <p className="text-[10px] text-teal-700 uppercase">Authenticated: {COSMIC_KEY_CONTEXT.persona.identity}</p>
        </div>
        <div className="mt-4 md:mt-0 w-full md:w-96">
          <StatusBoard />
        </div>
      </header>

      <main className="grid grid-cols-1 lg:grid-cols-4 gap-6 h-[calc(100vh-220px)]">
        <div className="lg:col-span-1 h-full">
            <ControlPanel
                features={FEATURES}
                selectedFeature={selectedFeature}
                onSelectFeature={setSelectedFeature}
                onGenerate={handleGenerate}
                isLoading={isLoading}
            />
        </div>
        <div className="lg:col-span-3 grid grid-rows-2 gap-6 h-full">
            <div className="row-span-1 h-full overflow-hidden border border-teal-950 rounded-lg">
                 <CodeEditor code={GD_SCRIPT_CODE} />
            </div>
            <div className="row-span-1 h-full overflow-hidden border border-teal-950 rounded-lg">
                <OutputDisplay 
                    output={output} 
                    isLoading={isLoading} 
                    featureTitle={selectedFeatureInfo?.title || 'System Response'}
                />
            </div>
        </div>
      </main>

      {error && (
        <div className="fixed bottom-4 right-4 max-w-sm bg-red-950 border border-red-500 text-red-400 p-4 rounded-lg shadow-2xl z-40">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 bg-red-500 rounded-full animate-ping"></div>
            <strong className="text-xs uppercase">Protocol Failure</strong>
          </div>
          <p className="text-[10px]">{error}</p>
        </div>
      )}

      <footer className="mt-4 text-[8px] text-teal-900 uppercase flex justify-between">
        <span>Ouroboros-8 Logic Fused // Gemini-3 Series Engine</span>
        <span>Sol Authority Governance: Article I-V Applied</span>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';

interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ output, isLoading, featureTitle }) => {
  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="flex flex-col items-center justify-center h-full text-teal-600">
          <div className="w-12 h-12 border-4 border-teal-900 border-t-teal-400 rounded-full animate-spin mb-4"></div>
          <p className="text-sm font-mono tracking-widest animate-pulse uppercase">Syncing with EchoPrime...</p>
        </div>
      );
    }

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full text-teal-900 opacity-30">
          <div className="text-8xl mb-4">⎔</div>
          <h3 className="text-xl font-bold uppercase tracking-tighter italic">Terminal Idle</h3>
          <p className="mt-2 text-[10px] text-center max-w-xs uppercase">
            Awaiting Command Execution from Nomadz Dev Deck.
          </p>
        </div>
      );
    }

    // Split output by lines and render Nomad-themed markdown
    const formattedOutput = output.split('\n').map((line, index) => {
        if (line.startsWith('# ')) return <h1 key={index} className="text-2xl font-black text-teal-400 mt-4 mb-2 uppercase italic border-b border-teal-900 inline-block">{line.substring(2)}</h1>;
        if (line.startsWith('## ')) return <h2 key={index} className="text-xl font-bold text-teal-500 mt-3 mb-2 uppercase">{line.substring(3)}</h2>;
        if (line.startsWith('### ')) return <h3 key={index} className="text-lg font-bold text-teal-600 mt-2 mb-1 uppercase tracking-tight">{line.substring(4)}</h3>;
        if (line.startsWith('* ') || line.startsWith('- ')) return <li key={index} className="ml-6 text-teal-400 list-none flex items-start gap-2"><span className="text-teal-700">▶</span>{line.substring(2)}</li>;
        if (line.startsWith('```')) return null; // Simple code block skip for now
        if (line.trim() === '') return <div key={index} className="h-2" />;
        return <p key={index} className="my-1 text-teal-200 text-sm font-mono tracking-tight leading-snug">{line}</p>;
    });

    return <div className="space-y-1">{formattedOutput}</div>;
  };

  return (
    <div className="bg-black border border-teal-950 rounded-lg shadow-inner h-full flex flex-col relative">
      {/* Grid background effect */}
      <div className="absolute inset-0 opacity-[0.02] pointer-events-none bg-[radial-gradient(#2dd4bf_1px,transparent_1px)] [background-size:16px_16px]"></div>

      <div className="px-4 py-2 bg-teal-950 border-b border-teal-900 flex justify-between items-center z-10">
        <h2 className="text-[10px] font-bold text-teal-400 uppercase tracking-widest">{featureTitle}</h2>
        <div className="text-[8px] text-teal-800 uppercase font-mono">Status: Stream_Live</div>
      </div>
      <div className="p-6 overflow-auto flex-grow z-10 custom-scrollbar">
        {renderContent()}
      </div>
    </div>
  );
};

export default OutputDisplay;

import React, { useEffect, useRef, useState } from 'react';

const CameraMonitor: React.FC = () => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [status, setStatus] = useState<'CONNECTING' | 'STABLE' | 'OFFLINE'>('CONNECTING');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ 
          video: { width: 320, height: 240, frameRate: 15 } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setStatus('STABLE');
        }
      } catch (err) {
        console.error("Camera access failed:", err);
        setStatus('OFFLINE');
        setError("SIGNAL LOST");
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  return (
    <div className="relative bg-black border-2 border-teal-900 rounded-lg overflow-hidden h-48 shadow-[0_0_20px_rgba(20,184,166,0.1)] group">
      {/* Scanline Overlay */}
