import React from 'react';
import { CameraSettings } from '../types';

interface CameraSettingsPanelProps {
  settings: CameraSettings;
  onUpdate: (settings: CameraSettings) => void;
  onClose: () => void;
  isActive: boolean;
}

const CameraSettingsPanel: React.FC<CameraSettingsPanelProps> = ({ settings, onUpdate, onClose, isActive }) => {
  if (!isActive) return null;

  const handleChange = (key: keyof CameraSettings, value: number | boolean) => {
    onUpdate({ ...settings, [key]: value });
  };

  const Slider = ({ label, value, min, max, onChange }: { label: string, value: number, min: number, max: number, onChange: (val: number) => void }) => (
    <div className="mb-4">
      <div className="flex justify-between items-center mb-1">
        <label className="text-[10px] text-teal-500 uppercase tracking-tighter font-bold">{label}</label>
        <span className="text-[10px] text-teal-400 font-mono">{value}%</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        value={value}
        onChange={(e) => onChange(parseInt(e.target.value))}
        className="w-full h-1 bg-teal-950 rounded-lg appearance-none cursor-pointer accent-teal-500"
      />
    </div>
  );

  return (
    <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-sm border-2 border-teal-500 rounded-lg p-4 flex flex-col animate-in fade-in zoom-in duration-200">
      <div className="flex justify-between items-center mb-4 border-b border-teal-900 pb-2">
        <h3 className="text-xs font-black text-teal-400 uppercase italic tracking-widest">Optic_Config_v1.2</h3>
        <button 
          onClick={onClose}
          className="text-teal-900 hover:text-teal-400 transition-colors text-lg font-bold"
        >
          [X]
        </button>
      </div>

      <div className="flex-grow space-y-2 overflow-y-auto custom-scrollbar">
        <Slider 
          label="Brightness" 
          value={settings.brightness} 
          min={0} 
          max={200} 
          onChange={(v) => handleChange('brightness', v)} 
        />
        <Slider 
          label="Contrast" 
          value={settings.contrast} 
          min={0} 
          max={200} 
          onChange={(v) => handleChange('contrast', v)} 
        />
        <Slider 
          label="Saturation" 
          value={settings.saturation} 
          min={0} 
          max={200} 
          onChange={(v) => handleChange('saturation', v)} 
        />

        <div className="flex items-center justify-between mt-4 p-2 bg-teal-950/30 rounded border border-teal-900/50">
          <label className="text-[10px] text-teal-500 uppercase font-bold">Grayscale Mode</label>
          <button
            onClick={() => handleChange('grayscale', !settings.grayscale)}
            className={`w-10 h-5 rounded-full transition-all relative ${settings.grayscale ? 'bg-teal-500' : 'bg-teal-950'}`}
          >
            <div className={`absolute top-1 w-3 h-3 rounded-full bg-black transition-all ${settings.grayscale ? 'left-6' : 'left-1'}`}></div>
          </button>
        </div>
      </div>

      <div className="mt-4 pt-2 border-t border-teal-900 flex justify-between">
        <button 
          onClick={() => onUpdate({ brightness: 100, contrast: 100, saturation: 100, grayscale: true })}
          className="text-[8px] text-teal-800 hover:text-teal-500 uppercase font-bold"
        >
          Reset_To_Nomad_Default
        </button>
        <span className="text-[8px] text-teal-900">SYSTEM_READY</span>
      </div>
    </div>
  );
};

