import React, { useEffect, useRef, useState } from 'react';
import { CameraSettings } from '../types';
import CameraSettingsPanel from './CameraSettingsPanel';

interface CameraMonitorProps {
  settings: CameraSettings;
  onUpdateSettings: (settings: CameraSettings) => void;
}

const CameraMonitor: React.FC<CameraMonitorProps> = ({ settings, onUpdateSettings }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [status, setStatus] = useState<'CONNECTING' | 'STABLE' | 'OFFLINE'>('CONNECTING');
  const [error, setError] = useState<string | null>(null);
  const [isConfigOpen, setIsConfigOpen] = useState(false);

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ 
          video: { width: 320, height: 240, frameRate: 15 } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          setStatus('STABLE');
        }
      } catch (err) {
        console.error("Camera access failed:", err);
        setStatus('OFFLINE');
        setError("SIGNAL LOST");
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const videoFilter = `
    brightness(${settings.brightness}%) 
    contrast(${settings.contrast}%) 
    saturate(${settings.saturation}%) 
    ${settings.grayscale ? 'grayscale(100%)' : ''}
  `;

  return (
    <div className="relative bg-black border-2 border-teal-900 rounded-lg overflow-hidden h-48 shadow-[0_0_20px_rgba(20,184,166,0.1)] group">
      {/* Settings Overlay */}
      <CameraSettingsPanel 
        isActive={isConfigOpen} 
        settings={settings} 
        onUpdate={onUpdateSettings} 
        onClose={() => setIsConfigOpen(false)} 
      />

      {/* Scanline Overlay */}
      <div className="absolute inset-0 pointer-events-none z-20 opacity-30 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%)] bg-[length:100%_4px]"></div>

      {/* Green Tint Overlay */}
      <div className="absolute inset-0 pointer-events-none z-10 bg-teal-500/10 mix-blend-color"></div>

      {/* Monitor Header */}
      <div className="absolute top-0 left-0 right-0 bg-teal-950/80 px-2 py-0.5 border-b border-teal-900 flex justify-between items-center z-30">
        <span className="text-[8px] font-bold text-teal-400 tracking-tighter uppercase">Visual_Feed // {status}</span>
        <div className="flex items-center gap-2">
          <button 
            onClick={() => setIsConfigOpen(true)}
            className="text-[8px] px-1 bg-teal-900 text-teal-400 border border-teal-700 hover:bg-teal-500 hover:text-black transition-all rounded uppercase font-black"
          >
            Config
          </button>
          <div className={`w-1 h-1 rounded-full ${status === 'STABLE' ? 'bg-teal-400 animate-pulse' : 'bg-red-500'}`}></div>
          <div className="w-1 h-1 rounded-full bg-teal-800"></div>
        </div>
      </div>

      {/* Scanning Elements */}
      <div className="absolute inset-0 z-30 pointer-events-none">
        {/* Corner Brackets */}
        <div className="absolute top-4 left-4 w-4 h-4 border-t-2 border-l-2 border-teal-500/50"></div>
        <div className="absolute top-4 right-4 w-4 h-4 border-t-2 border-r-2 border-teal-500/50"></div>
        <div className="absolute bottom-4 left-4 w-4 h-4 border-b-2 border-l-2 border-teal-500/50"></div>
        <div className="absolute bottom-4 right-4 w-4 h-4 border-b-2 border-r-2 border-teal-500/50"></div>

        {/* Scanning Line */}
        <div className="absolute top-0 left-0 w-full h-px bg-teal-400/30 shadow-[0_0_10px_teal] animate-[scan_4s_linear_infinite]"></div>
      </div>

      {/* Video / Error State */}
      {status === 'OFFLINE' ? (
        <div className="flex flex-col items-center justify-center h-full bg-gray-950 text-teal-900">
          <div className="text-4xl mb-2 opacity-20">⚠</div>
          <div className="text-[10px] font-black uppercase tracking-widest">{error}</div>
        </div>
      ) : (
        <video 
          ref={videoRef} 
          autoPlay 
          muted 
          playsInline 
          style={{ filter: videoFilter }}
          className="w-full h-full object-cover scale-x-[-1]"
        />
      )}

      {/* Data Overlay */}
      <div className="absolute bottom-2 left-2 z-30 text-[7px] text-teal-400/70 font-mono flex flex-col uppercase">
        <span>FR: 15.0 FPS</span>
        <span>ID: NOMADZ_OPTIC</span>
      </div>
      <div className="absolute bottom-2 right-2 z-30 text-[7px] text-teal-400/70 font-mono text-right uppercase">
        <span>LVL: L4_DEEP</span>
        <span>{new Date().toLocaleTimeString()}</span>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes scan {
          0% { top: 0; }
          100% { top: 100%; }
        }
      `}} />
    </div>
  );
};

