const AssetNode: React.FC<{ asset: MotherBrainAsset, level: number }> = ({ asset, level }) => {
  const [isOpen, setIsOpen] = useState(level < 1);
  const hasChildren = asset.children && asset.children.length > 0;

  const getIcon = () => {
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      default: return '📄';
    }
  };

  return (
    <div className="font-mono text-[10px] select-none">
      <div 
        className={`flex items-center gap-2 py-1 px-2 cursor-pointer transition-colors ${
          asset.type === 'folder' ? 'text-teal-400 hover:bg-teal-950' : 'text-teal-600 hover:bg-teal-900/20'
        }`}
        style={{ paddingLeft: `${level * 12 + 8}px` }}
        onClick={() => hasChildren && setIsOpen(!isOpen)}
      >
        <span className="opacity-50">{getIcon()}</span>
        <span className={asset.type === 'godot_project' ? 'font-bold underline decoration-teal-900' : ''}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div>
          {asset.children!.map(child => (
            <AssetNode key={child.id} asset={child} level={level + 1} />
          ))}
        </div>
      )}
    </div>
  );
};

