            <h4 className="text-[10px] font-bold text-teal-400 uppercase tracking-widest mb-2">V-Motion Synthesis Output</h4>
            <p className="text-[10px] text-teal-700 leading-relaxed uppercase">
              Retro-futuristic temporal scan complete. Simulation stabilized at 1080p. 
              NOMADZ_OPTIC signature verified.
            </p>
          </div>
        </div>
      );
    }

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full text-teal-900 opacity-30">
          <div className="text-8xl mb-4">⎔</div>
          <h3 className="text-xl font-bold uppercase tracking-tighter italic">Terminal Idle</h3>
          <p className="mt-2 text-[10px] text-center max-w-xs uppercase">
            Awaiting Command Execution from Nomadz Dev Deck.
          </p>
        </div>
      );
    }

    // Split output by lines and render Nomad-themed markdown
    const formattedOutput = output.split('\n').map((line, index) => {
        if (line.startsWith('# ')) return <h1 key={index} className="text-2xl font-black text-teal-400 mt-4 mb-2 uppercase italic border-b border-teal-900 inline-block">{line.substring(2)}</h1>;
        if (line.startsWith('## ')) return <h2 key={index} className="text-xl font-bold text-teal-500 mt-3 mb-2 uppercase">{line.substring(3)}</h2>;
        if (line.startsWith('### ')) return <h3 key={index} className="text-lg font-bold text-teal-600 mt-2 mb-1 uppercase tracking-tight">{line.substring(4)}</h3>;
        if (line.startsWith('* ') || line.startsWith('- ')) return <li key={index} className="ml-6 text-teal-400 list-none flex items-start gap-2"><span className="text-teal-700">▶</span>{line.substring(2)}</li>;
        if (line.startsWith('```')) return null; // Simple code block skip for now
        if (line.trim() === '') return <div key={index} className="h-2" />;
        return <p key={index} className="my-1 text-teal-200 text-sm font-mono tracking-tight leading-snug">{line}</p>;
    });

    return <div className="space-y-1">{formattedOutput}</div>;
  };

  return (
    <div className="bg-black border border-teal-950 rounded-lg shadow-inner h-full flex flex-col relative overflow-hidden">
      {/* Grid background effect */}
      <div className="absolute inset-0 opacity-[0.02] pointer-events-none bg-[radial-gradient(#2dd4bf_1px,transparent_1px)] [background-size:16px_16px]"></div>

      <div className="px-4 py-2 bg-teal-950 border-b border-teal-900 flex justify-between items-center z-10">
