import { Feature, CameraSettings } from './types';
import { generateContent } from './services/geminiService';
import { GoogleGenAI } from "@google/genai";

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.EXPLAIN_CODE);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [videoUrl, setVideoUrl] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);

  // Camera settings state
  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 125,
    contrast: 125,
    saturation: 100,
    grayscale: true
  });

  const handleOpenApiKey = async () => {
    await window.aistudio.openSelectKey();
    setRequiresApiKey(false);
  };

  const handleGenerateVideo = async () => {
    setIsLoading(true);
    setVideoUrl(undefined);
    setOutput('');
    setLoadingStatus('Initializing V-Motion link...');

    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setRequiresApiKey(true);
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

      // Step 1: Generate a prompt for Veo based on GDScript
      setLoadingStatus('Synthesizing temporal prompt...');
      const promptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a descriptive visual prompt for a 6-second video based on this GDScript code for a 16-bit universe generator. 
        Focus on a retro-futuristic, Saturday morning cartoon aesthetic. The prompt should be suitable for a high-quality video generator like Veo.
        Code: ${GD_SCRIPT_CODE}`,
        config: {
          systemInstruction: "You are a visual director for retro sci-fi animations. Provide only the prompt text."
        }
      });

      const videoPrompt = promptResponse.text || "A retro-futuristic 16-bit galaxy spinning in deep space, vibrant neon toxic greens and lush pinks, high contrast, Saturday morning cartoon style.";

      // Step 2: Start Veo video generation
      setLoadingStatus('V-Motion core active. Rendering simulation...');
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: videoPrompt,
        config: {
          numberOfVideos: 1,
          resolution: '1080p',
          aspectRatio: '16:9'
        }
      });

      const statusMessages = [
        'Calculating planet trajectories...',
        'Compiling star systems...',
        'Injecting 16-bit color palettes...',
        'Finalizing temporal stream...',
        'Verifying Ouroboros protocol...'
      ];
      let statusIdx = 0;

      while (!operation.done) {
        setLoadingStatus(statusMessages[statusIdx % statusMessages.length]);
        statusIdx++;
        await new Promise(resolve => setTimeout(resolve, 10000));

        try {
          operation = await ai.operations.getVideosOperation({ operation: operation });
