      <header className="mb-6 flex flex-col md:flex-row items-center justify-between border-b-2 border-teal-900 pb-4">
        <div>
          <h1 className="text-3xl font-black text-teal-400 italic tracking-tighter">
            COSMIC KEY <span className="text-teal-800 text-xl font-normal">NOMADZ_TERM_0.0.1</span>
          </h1>
          <p className="text-[10px] text-teal-700 uppercase">Authenticated: {COSMIC_KEY_CONTEXT.persona.identity}</p>
        </div>
        <div className="mt-4 md:mt-0 w-full md:w-96">
          <StatusBoard />
        </div>
      </header>

      <main className="grid grid-cols-1 lg:grid-cols-5 gap-6 h-[calc(100vh-210px)]">
        {/* Left Side: Comms & Assets */}
        <div className="lg:col-span-1 flex flex-col gap-4 overflow-hidden h-full">
            <div className="flex-shrink-0">
              <CameraMonitor 
                settings={cameraSettings} 
                onUpdateSettings={setCameraSettings} 
              />
            </div>
            <div className="flex-grow overflow-hidden">
              <MotherBrainRepo />
            </div>
        </div>

        {/* Center: Controls */}
        <div className="lg:col-span-1 h-full">
            <ControlPanel
                features={FEATURES}
                selectedFeature={selectedFeature}
                onSelectFeature={setSelectedFeature}
                onGenerate={handleGenerate}
