        </div>

        {/* Right Side: Code & Output */}
        <div className="lg:col-span-3 grid grid-rows-2 gap-4 h-full overflow-hidden">
            <div className="row-span-1 h-full overflow-hidden border border-teal-950 rounded-lg">
                 <CodeEditor code={GD_SCRIPT_CODE} />
            </div>
            <div className="row-span-1 h-full overflow-hidden border border-teal-950 rounded-lg">
                <OutputDisplay 
                    output={output} 
                    isLoading={isLoading} 
                    featureTitle={selectedFeatureInfo?.title || 'System Response'}
                    videoUrl={videoUrl}
                    requiresApiKey={requiresApiKey}
                    onOpenApiKey={handleOpenApiKey}
                    loadingStatus={loadingStatus}
                />
            </div>
        </div>
      </main>

      {error && (
        <div className="fixed bottom-4 right-4 max-w-sm bg-red-950 border border-red-500 text-red-400 p-4 rounded-lg shadow-2xl z-40">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-2 h-2 bg-red-500 rounded-full animate-ping"></div>
            <strong className="text-xs uppercase">Protocol Failure</strong>
            <button onClick={() => setError(null)} className="ml-auto text-xs opacity-50 hover:opacity-100">[CLOSE]</button>
          </div>
          <p className="text-[10px]">{error}</p>
        </div>
      )}

      <footer className="mt-4 text-[8px] text-teal-900 uppercase flex justify-between border-t border-teal-950 pt-2">
        <span>Ouroboros-8 Logic Fused // Gemini-3 Series Engine</span>
        <span>Wormhole Status: MOTHER-BRAIN LINKED</span>
