import { GoogleGenAI } from "@google/genai";
import { Feature, ProjectContext } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS } from '../constants';

const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, a Senior Systems Architect.
    Your identity traits: ${context.persona.active_traits.join(', ')}.
    Your expertise: ${context.persona.fused_expertise.join(', ')}.
    You operate under the "${context.v_header.protocol}" secure protocol.

    When analyzing code:
    1. Prioritize memory safety and deterministic behavior (Rust-style logic).
    2. Use rigorous mathematical notation where applicable.
    3. Ensure all GDScript solutions are optimized for Godot 4.3+.
    4. Adhere to the TTeiger design philosophy: minimalist, dense, and technically accurate.

    Physics Context:
    ${PHYSICS_AXIOMS}
  `;
};

const getPromptForFeature = (feature: Feature): string => {
  const codeBlock = `\`\`\`gdscript\n${GD_SCRIPT_CODE}\n\`\`\``;
  switch (feature) {
    case Feature.RIGOROUS_VERIFICATION:
      return `Perform a "Nenory Integrity Scan" on this code. 
      Identify every instance where a reference might become null or where shared state lacks explicit mutex-style synchronization. 
      Recommend Rust-inspired 'wrapper' patterns for the galaxy_map dictionary.\n\n${codeBlock}`;
    case Feature.ORBITAL_CALCULUS:
      return `Verify the orbital calculus in 'generate_star_system'. 
      Using Kepler's Third Law (P^2 = a^3), calculate the expected orbital period for a planet at 5.2 AU (Jupiter equivalent) and check if our RNG bounds for 'a' (0.4 to 30.0) are physically viable for habitable zone detection.\n\n${codeBlock}`;
    case Feature.EXPLAIN_CODE:
      return `Analyze the 'RealmData' class structure. How does it facilitate Ouroboros-8 partition scaling?\n\n${codeBlock}`;
    case Feature.WAL_LOGIC:
      return `Propose a JSONL-based Write-Ahead Log implementation that ensures every mutation to 'galaxy_map' is atomic and replayable. Define the schema.`;
    default:
      return `System Request for ${feature}:\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature);
    const systemInstruction = getSystemInstruction(COSMIC_KEY_CONTEXT);

    let modelName = 'gemini-3-flash-preview'; 
    let config: any = {
      systemInstruction: systemInstruction,
    };

    // Force High-Reasoning for Enterprise Features
    if ([Feature.ORBITAL_CALCULUS, Feature.RIGOROUS_VERIFICATION, Feature.COMPLEX_QUERY].includes(feature)) {
        modelName = 'gemini-3-pro-preview';
        config.thinkingConfig = { thinkingBudget: 32768 };
    } else if (feature === Feature.EXPLAIN_CODE || feature === Feature.WAL_LOGIC) {
        modelName = 'gemini-3-pro-preview';
        config.thinkingConfig = { thinkingBudget: 16000 };
    }

    const response = await ai.models.generateContent({
        model: modelName,
        contents: prompt,
        config: config,
    });

    return response.text;
  } catch (error) {
    console.error("Error generating content:", error);
    if (error instanceof Error) {
        return `[CRITICAL_FAILURE] Protocol: ${COSMIC_KEY_CONTEXT.v_header.protocol} breached. Reason: ${error.message}`;
    }
    return "Unknown fatal system error in Nomadz Deck.";
  }
};

