const AssetNode: React.FC<{ asset: MotherBrainAsset, level: number }> = ({ asset, level }) => {
  const [isOpen, setIsOpen] = useState(level < 1);
  const hasChildren = asset.children && asset.children.length > 0;

  const getIcon = () => {
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      default: return '📄';
    }
  };

  return (
    <div className="font-mono text-[9px] select-none">
      <div 
        className={`flex items-center gap-2 py-1 px-2 cursor-pointer transition-all border-l-2 border-transparent ${
          asset.type === 'folder' 
            ? 'text-earth font-black hover:bg-bone hover:border-neonOrange' 
            : 'text-dust hover:text-earth hover:bg-bone/40'
        }`}
        style={{ paddingLeft: `${level * 10 + 8}px` }}
        onClick={() => hasChildren && setIsOpen(!isOpen)}
      >
        <span className="opacity-60 grayscale">{getIcon()}</span>
        <span className={asset.type === 'godot_project' ? 'text-neonOrange' : ''}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-tan/30 ml-3">
          {asset.children!.map(child => (
            <AssetNode key={child.id} asset={child} level={level + 1} />
          ))}
        </div>
      )}
    </div>
  );
};

