import React, { useState, useCallback } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT } from './constants';
import { Feature, CameraSettings } from './types';
import { generateContent } from './services/geminiService';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.RIGOROUS_VERIFICATION);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [videoUrl, setVideoUrl] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const handleOpenApiKey = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setRequiresApiKey(false);
  };

  const handleGenerateVideo = async () => {
    setIsLoading(true);
    setVideoUrl(undefined);
    setOutput('');
    setLoadingStatus('RE-INITIALIZING_VEO_PIPELINE');

    try {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setRequiresApiKey(true);
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      setLoadingStatus('CONSTRUCTING_3D_BONE_MODEL');

      const promptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a brutalist retro-sci-fi video prompt. Colors: Cream/Bone background, Neon Orange/Green accents. Subject: Cosmic planetary orbits spinning in high-contrast technical simulation style.`,
        config: { systemInstruction: "Output only the video prompt string." }
      });

      const videoPrompt = promptResponse.text || "16-bit planetary orbits spinning, neon green lines on bone-white background, glitchy brutalist terminal effect.";

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: videoPrompt,
        config: { numberOfVideos: 1, resolution: '1080p', aspectRatio: '16:9' }
      });

      while (!operation.done) {
        setLoadingStatus(`V-MOTION_PHASE_${Math.floor(Math.random() * 999)}`);
        await new Promise(resolve => setTimeout(resolve, 8000));
        operation = await ai.operations.getVideosOperation({ operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  };

  const handleGenerate = useCallback(async () => {
    if (selectedFeature === Feature.VIDEO_GENERATION) {
      handleGenerateVideo();
      return;
    }
    setIsLoading(true);
    setVideoUrl(undefined);
    setRequiresApiKey(false);
    setError(null);
    const result = await generateContent(selectedFeature);
    setOutput(result);
    setIsLoading(false);
  }, [selectedFeature]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);

  return (
    <div className="h-full flex flex-col p-6 gap-6 bg-bone text-earth selection:bg-neonOrange selection:text-white">
      {/* Top Bar / Header with high neon accent */}
      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2">
        <div className="flex items-center gap-6">
          <div className="w-10 h-10 bg-earth flex items-center justify-center shadow-neon-orange">
             <span className="text-neonOrange text-2xl font-black">⎔</span>
          </div>
          <div className="flex flex-col">
            <h1 className="text-2xl font-black uppercase tracking-[-0.05em] text-earth">
              NOMADZ_DEV_DECK <span className="text-neonOrange neon-text-glow-orange italic">V3.5_EXTREME</span>
            </h1>
            <p className="text-[10px] font-black uppercase text-dust">HANDSHAKE: <span className="text-neonGreen neon-text-glow-green">{COSMIC_KEY_CONTEXT.persona.identity}</span></p>
          </div>
        </div>
        <div className="flex items-center gap-8">
          <div className="flex flex-col items-end gap-1">
             <div className="text-[10px] font-black text-neonOrange">SIMULATION_ACTIVE</div>
             <div className="flex gap-1.5">
               <div className="w-4 h-1 bg-neonGreen shadow-neon-green"></div>
               <div className="w-4 h-1 bg-neonOrange shadow-neon-orange"></div>
               <div className="w-4 h-1 bg-dust"></div>
             </div>
          </div>
          <StatusBoard />
        </div>
      </header>

      {/* Main Grid */}
      <main className="flex-grow grid grid-cols-12 gap-8 overflow-hidden">
        {/* Left Column: Vision & Assets */}
        <div className="col-span-2 flex flex-col gap-6 overflow-hidden">
          <div className="shadow-neon-orange">
            <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          </div>
          <div className="flex-grow overflow-hidden border-2 border-earth">
            <MotherBrainRepo />
          </div>
        </div>

        {/* Center Column: Control Nucleus */}
        <div className="col-span-3 h-full overflow-hidden">
          <ControlPanel
            features={FEATURES}
            selectedFeature={selectedFeature}
            onSelectFeature={setSelectedFeature}
            onGenerate={handleGenerate}
            isLoading={isLoading}
          />
        </div>

        {/* Right Column: Execution & Output */}
        <div className="col-span-7 flex flex-col gap-8 overflow-hidden">
          <div className="h-1/2 overflow-hidden">
            <CodeEditor code={GD_SCRIPT_CODE} />
          </div>
          <div className="h-1/2 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedFeatureInfo?.title || 'Execution_Buffer'}
              videoUrl={videoUrl}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
            />
          </div>
        </div>
      </main>

      {/* Footer Branding - High Brutalism */}
      <footer className="shrink-0 flex justify-between items-center text-[10px] font-black uppercase text-dust border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonGreen"></div> PROTOCOL: OUROBOROS_SECURE_EXTREME</span>
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonOrange"></div> RIGOR_SCAN: MULTI_THREADED</span>
        </div>
        <div className="flex gap-8 italic">
          <span>{new Date().toLocaleTimeString()} (Z)</span>
          <span className="text-neonOrange neon-text-glow-orange border-b border-neonOrange">AUTH: SOL_AUTHORITY_SECURE</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-10 right-10 bg-earth border-4 border-neonOrange p-6 shadow-[10px_10px_0px_#ff5c00] z-50 max-w-sm animate-bounce text-white">
          <div className="flex justify-between items-center mb-4 border-b border-neonOrange pb-2">
            <span className="text-neonOrange font-black text-sm uppercase neon-text-glow-orange">[CRITICAL_FAULT]</span>
            <button onClick={() => setError(null)} className="text-[12px] font-black hover:text-neonOrange">X</button>
          </div>
          <p className="text-[11px] uppercase font-mono leading-relaxed">{error}</p>
          <div className="mt-4 text-[9px] text-neonOrange opacity-50">Handshake_Timeout_Protocol_B</div>
        </div>
      )}
