interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId }) => {
  const [isOpen, setIsOpen] = useState(level < 1 || asset.id === 'ai-core-yellow');
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.id === 'ai-core-yellow') return '📂';
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      case 'image_asset': return '🖼️';
      default: return '📄';
    }
  };

  const handleClick = () => {
    if (hasChildren) {
      setIsOpen(!isOpen);
    } else {
      onSelect(asset);
    }
  };

  const style = asset.color && asset.type === 'folder' 
    ? { borderLeft: `4px solid ${asset.color}`, color: asset.color } 
    : {};

  return (
    <div className="font-mono text-[9px] select-none">
      <div 
        className={`flex items-center gap-2 py-1 px-2 cursor-pointer transition-all border-l-2 ${
          isSelected 
            ? 'bg-neonOrange/10 border-neonOrange text-earth' 
            : 'border-transparent text-dust hover:bg-bone hover:border-tan hover:text-earth'
        }`}
        style={{ paddingLeft: `${level * 10 + 8}px`, ...style }}
        onClick={handleClick}
      >
        <span className={`opacity-80 ${isSelected ? 'scale-110' : ''}`}>{getIcon()}</span>
        <span className={`${asset.type === 'godot_project' ? 'text-neonOrange font-black' : ''} ${isSelected ? 'font-black' : ''} ${asset.id === 'ai-core-yellow' ? 'font-black tracking-widest uppercase' : ''}`}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-tan/30 ml-3">
          {asset.children!.map(child => (
            <AssetNode key={child.id} asset={child} level={level + 1} onSelect={onSelect} selectedId={selectedId} />
          ))}
        </div>
      )}
    </div>
  );
};

