          <div className="bg-earth/5 border-2 border-tan p-4 flex flex-col justify-between shadow-sm">
             <span className="text-[10px] font-black uppercase text-dust italic">MCP_Handshake</span>
             <div className="text-xs font-mono text-earth font-bold">PROT: OUROBOROS-8<br/>STAT: ACTIVE_SYNC<br/>ADDR: 0x88A21</div>
             <div className="w-full h-1 bg-dust/20"></div>
          </div>
        </div>
        <div className="flex-grow bg-earth border-2 border-neonOrange p-6 flex flex-col relative overflow-hidden shadow-neon-orange">
          <div className="absolute inset-0 brutalist-grid opacity-10"></div>
          <div className="z-10 flex justify-between items-start">
            <div>
              <h3 className="text-neonOrange text-lg font-black italic tracking-widest uppercase">{selectedImageName}</h3>
              <p className="text-bone/60 text-[8px] font-black uppercase tracking-widest mt-1">Nenory_Visual_Kernel_v3.2</p>
            </div>
            <div className="text-neonGreen text-xl font-black italic">NOMADZ_EXEC</div>
          </div>
          <div className="flex-grow mt-6 flex items-end justify-between">
            <div className="flex gap-2">
              {[1,2,3,4,5,6,7,8].map(i => (
                <div key={i} className="w-4 bg-neonGreen/40 border-t-2 border-neonGreen animate-[pulse_2s_infinite]" style={{ height: `${20 + Math.random() * 60}%`, animationDelay: `${i * 0.1}s` }}></div>
              ))}
            </div>
            <div className="text-right">
              <div className="text-[9px] font-black text-bone/40 mb-2 uppercase tracking-tighter">Scan_Frequency</div>
              <div className="text-2xl font-black text-bone">8.4 GHZ</div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    if (requiresApiKey) {
      return (
        <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-bone/20 shadow-neon-orange">
          <div className="text-5xl mb-4 animate-pulse">🔒</div>
          <h3 className="text-[12px] font-black uppercase text-neonOrange mb-2 neon-text-glow-orange tracking-[0.2em]">AUTH_REQUIRED: L5_CRYPT</h3>
          <p className="text-[10px] text-center mb-6 max-w-xs uppercase leading-relaxed text-earth font-bold">Establish project-link with valid billing authority.</p>
          <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 hover:bg-earth transition-all hover:scale-105 uppercase text-[11px] tracking-widest shadow-neon-orange">Authenticate_Key_Buffer</button>
        </div>
      );
    }

    if (isLoading) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-tan relative overflow-hidden mb-6 shadow-neon-orange">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange neon-text-glow-orange animate-pulse">SYNTHESIZING_REALM_DATA</p>
          {loadingStatus && <p className="text-[9px] text-earth uppercase mt-3 font-mono font-bold">THREAD_LOG >> <span className="text-neonOrange">{loadingStatus}</span></p>}
        </div>
      );
    }

    if (videoUrl) {
      return (
        <div className="flex flex-col h-full bg-black border-2 border-neonGreen shadow-neon-green overflow-hidden group">
          <video src={videoUrl} controls autoPlay loop className="w-full h-auto aspect-video grayscale group-hover:grayscale-0 transition-all duration-700" />
          <div className="p-3 bg-cream border-t-2 border-neonGreen flex justify-between items-center">
            <div className="flex flex-col"><h4 className="text-[11px] font-black text-neonGreen uppercase tracking-widest neon-text-glow-green">VMOTION_BUFFER_FLIP_OK</h4><p className="text-[8px] text-dust font-bold">TIMESTAMP: {new Date().toISOString()}</p></div>
            <div className="px-3 py-1 bg-neonGreen text-earth text-[10px] font-black shadow-neon-green">VALIDATED_L5</div>
          </div>
        </div>
      );
    }

    if (isGeologosActive) {
      return renderGeologosPillars();
    }

    if (isImageSelected) {
      return renderDashboardViz();
    }

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
          <div className="text-6xl font-black text-dust mb-4 rotate-12">⎔</div>
          <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">Nenory_Standby_Mode</p>
          <div className="mt-4 flex gap-2">
            {[1, 2, 3].map(i => <div key={i} className="w-1.5 h-1.5 bg-tan animate-bounce" style={{ animationDelay: `${i * 0.2}s` }}></div>)}
          </div>
        </div>
      );
    }

    const formattedOutput = output.split('\n').map((line, index) => {
        if (line.startsWith('# ')) return <h1 key={index} className="text-[13px] font-black text-neonOrange mt-6 mb-3 uppercase border-b-4 border-neonOrange pb-1 neon-text-glow-orange">{line.substring(2)}</h1>;
        if (line.startsWith('## ')) return <h2 key={index} className="text-[11px] font-black text-earth mt-4 mb-2 uppercase tracking-widest border-l-4 border-neonOrange pl-2">{line.substring(3)}</h2>;
        if (line.startsWith('### ')) return <h3 key={index} className="text-[10px] font-black text-dust mt-3 uppercase border-b border-tan pb-1 italic">{line.substring(4)}</h3>;
        if (line.startsWith('* ') || line.startsWith('- ')) return (
          <div key={index} className="text-[10px] text-earth font-bold py-1.5 flex items-start gap-3 group/line">
            <span className="text-neonGreen neon-text-glow-green group-hover/line:translate-x-1 transition-transform">▶</span>
            <span className="group-hover/line:text-neonOrange transition-colors">{line.substring(2)}</span>
          </div>
        );
        if (line.trim() === '') return <div key={index} className="h-4" />;
        return <p key={index} className="text-[11px] text-earth font-mono leading-relaxed mb-3 border-l border-tan/30 pl-4">{line}</p>;
    });

    return (
      <div key={flipKey} className="page-flip-enter space-y-0 p-4 bg-white/40 border border-tan/20">
        {formattedOutput}
        <div className="mt-8 pt-4 border-t-2 border-tan/20 text-[8px] font-bold text-dust flex justify-between uppercase">
          <span>Page_End_Buffer</span>
          <span>Nomadz_Archival_Sync</span>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-tan h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_#332d2911]">
      <div className="px-4 py-2 bg-earth border-b-2 border-neonOrange flex justify-between items-center z-20 shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-3 h-3 bg-neonOrange shadow-neon-orange animate-pulse"></div>
          <h2 className="text-[10px] font-black text-bone uppercase tracking-[0.2em]">{featureTitle}</h2>
        </div>
        <div className="flex gap-4 text-[9px] font-black text-bone">
          <span className="text-neonGreen neon-text-glow-green">BUFFER_0x{Date.now().toString(16).slice(-4).toUpperCase()}</span>
          <span className="opacity-50">STABLE_OS</span>
        </div>
      </div>
      <div className="flex-grow overflow-auto custom-scrollbar z-10 p-2 brutalist-grid" style={{ perspective: '2000px' }}>
        {renderContent()}
      </div>
      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes loading { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
      `}} />
    </div>
  );
};

export default OutputDisplay;

import React, { useState, useCallback, useEffect } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT } from './constants';
import { Feature, CameraSettings, MotherBrainAsset } from './types';
import { generateContent } from './services/geminiService';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.SYSTEM_AUDIT);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [videoUrl, setVideoUrl] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [theme, setTheme] = useState<'bone' | 'void' | 'brutalist' | 'yellow'>('bone');
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const handleOpenApiKey = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setRequiresApiKey(false);
  };

  const handleGenerateVideo = async () => {
    setIsLoading(true);
    setVideoUrl(undefined);
    setOutput('');
    setLoadingStatus('RE-INITIALIZING_VEO_PIPELINE');

    try {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setRequiresApiKey(true);
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      setLoadingStatus('CONSTRUCTING_3D_BONE_MODEL');

      const promptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a brutalist retro-sci-fi video prompt. Colors: Cream/Bone background, Neon Orange/Green accents. Subject: Cosmic planetary orbits spinning in high-contrast technical simulation style.`,
        config: { systemInstruction: "Output only the video prompt string." }
      });

      const videoPrompt = promptResponse.text || "16-bit planetary orbits spinning, neon green lines on bone-white background, glitchy brutalist terminal effect.";

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: videoPrompt,
        config: { numberOfVideos: 1, resolution: '1080p', aspectRatio: '16:9' }
      });

      while (!operation.done) {
        setLoadingStatus(`V-MOTION_PHASE_${Math.floor(Math.random() * 999)}`);
        await new Promise(resolve => setTimeout(resolve, 8000));
        operation = await ai.operations.getVideosOperation({ operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  };

  const handleGenerate = useCallback(async () => {
    if (selectedFeature === Feature.VIDEO_GENERATION) {
      handleGenerateVideo();
      return;
    }

    if (selectedFeature === Feature.CUSTOM_INTEGRATION || selectedFeature === Feature.MCP_INTERFACE) {
      setOutput(`[INTEGRATION_LOG] Initializing connection to chosen node...\n- Status: HANDSHAKING\n- Protocol: MCP-1.0\n- Response: READY_FOR_CONTEXT_STREAM\n\n- Detected Nodes: LOCAL_MCP, NENORY_LLM_CORE\n- Latency: 12ms`);
      return;
    }

    setIsLoading(true);
    setVideoUrl(undefined);
    setRequiresApiKey(false);
    setError(null);
    setLoadingStatus(selectedFeature === Feature.SYSTEM_AUDIT ? 'AUDITING_PROTOCOL_HANDSHAKES' : 'PENETRATING_REPO_BUFFERS');

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;
    const targetName = selectedAsset?.name || 'buffer.gd';

    const result = await generateContent(selectedFeature, targetCode, targetName);
    setOutput(result);
    setIsLoading(false);
    setLoadingStatus(undefined);
  }, [selectedFeature, selectedAsset]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);

  return (
    <div className="h-full flex flex-col p-6 gap-6 bg-bone text-earth selection:bg-neonOrange selection:text-white transition-colors duration-500 overflow-hidden">
      {/* Top Bar / Header */}
      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-neon-orange border-2 border-neonOrange">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange">&lt;V&gt;</span>
          </div>
          <div className="flex flex-col">
            <h1 className="text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-neonOrange neon-text-glow-orange italic text-sm tracking-widest">V3.5_EXTREME</span>
            </h1>
            <p className="text-[10px] font-black uppercase text-dust">HANDSHAKE: <span className="text-neonGreen neon-text-glow-green">{COSMIC_KEY_CONTEXT.persona.identity}</span></p>
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex gap-2">
            {(['bone', 'void', 'brutalist', 'yellow'] as const).map(t => (
              <button 
                key={t}
                onClick={() => setTheme(t)}
                className={`w-4 h-4 border-2 ${theme === t ? 'border-neonOrange scale-125' : 'border-tan opacity-50'} transition-all`}
                title={`Switch to ${t} theme`}
                style={{ backgroundColor: t === 'bone' ? '#f5f2e8' : t === 'void' ? '#0a0a0a' : t === 'yellow' ? '#FFD700' : '#fff' }}
              />
            ))}
          </div>
          <div className="flex flex-col items-end gap-1">
             <div className="text-[10px] font-black text-neonOrange">SIMULATION_ACTIVE</div>
             <div className="flex gap-1.5">
               <div className="w-4 h-1 bg-neonGreen shadow-neon-green"></div>
               <div className="w-4 h-1 bg-neonOrange shadow-neon-orange"></div>
               <div className="w-4 h-1 bg-dust"></div>
             </div>
          </div>
          <StatusBoard />
        </div>
      </header>

      {/* Main Grid */}
      <main className="flex-grow grid grid-cols-12 gap-8 overflow-hidden">
        {/* Left Column: Vision & Assets */}
        <div className="col-span-2 flex flex-col gap-6 overflow-hidden">
          <div className="shadow-neon-orange">
            <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          </div>
          <div className="flex-grow overflow-hidden border-2 border-earth">
            <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} />
          </div>
        </div>

        {/* Center Column: Control Nucleus */}
        <div className="col-span-3 h-full overflow-hidden">
          {selectedFeature === Feature.CUSTOM_INTEGRATION || selectedFeature === Feature.MCP_INTERFACE ? (
            <IntegrationHub />
          ) : (
            <ControlPanel
              features={FEATURES}
              selectedFeature={selectedFeature}
              onSelectFeature={setSelectedFeature}
              onGenerate={handleGenerate}
              isLoading={isLoading}
            />
          )}
        </div>

        {/* Right Column: Execution & Output */}
        <div className="col-span-7 flex flex-col gap-8 overflow-hidden">
          <div className="h-1/2 overflow-hidden">
            {selectedAsset?.type === 'image_asset' ? (
              <div className="h-full bg-earth/10 border-2 border-tan flex items-center justify-center relative overflow-hidden group">
                <div className="absolute inset-0 brutalist-grid opacity-20"></div>
                <div className="text-center z-10 transition-transform group-hover:scale-110 duration-500">
                   <div className="text-5xl mb-4 drop-shadow-lg">🖼️</div>
                   <p className="text-[10px] font-black uppercase text-earth tracking-widest">{selectedAsset.name}</p>
                   <p className="text-[8px] text-dust font-bold mt-1 opacity-60">KERNEL_PATH: {selectedAsset.path}</p>
                </div>
                <div className="absolute bottom-4 right-4 bg-safetyYellow text-black px-2 py-1 text-[8px] font-black border border-black shadow-[2px_2px_0px_#000]">AI_CORE_READY</div>
              </div>
            ) : selectedAsset?.type === 'data_pillar' ? (
              <div className="h-full bg-safetyYellow/5 border-2 border-safetyYellow flex items-center justify-center relative overflow-hidden group">
                <div className="absolute inset-0 brutalist-grid opacity-20"></div>
                <div className="text-center z-10">
                   <div className="text-5xl mb-4 animate-bounce">🏛️</div>
                   <p className="text-[10px] font-black uppercase text-earth tracking-widest">{selectedAsset.name}</p>
                   <p className="text-[8px] text-dust font-bold mt-1">TYPE: GEOLOGOS_STRATA_PILLAR</p>
                </div>
              </div>
            ) : (
              <CodeEditor code={selectedAsset?.code || GD_SCRIPT_CODE} fileName={selectedAsset?.name} />
            )}
          </div>
          <div className="h-1/2 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedAsset?.type === 'image_asset' ? 'AI_CORE_VIZ' : (selectedFeatureInfo?.title || 'Execution_Buffer')}
              videoUrl={videoUrl}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
              isImageSelected={selectedAsset?.type === 'image_asset'}
              selectedImageName={selectedAsset?.name}
              isGeologosActive={selectedFeature === Feature.GEOLOGOS_INTEGRATION || selectedAsset?.type === 'data_pillar'}
            />
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="shrink-0 flex justify-between items-center text-[10px] font-black uppercase text-dust border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonGreen"></div> PROTOCOL: OUROBOROS_SECURE_EXTREME</span>
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonOrange"></div> RIGOR_SCAN: MULTI_THREADED</span>
        </div>
        <div className="flex gap-8 italic">
          <span>{new Date().toLocaleTimeString()} (Z)</span>
          <span className="text-neonOrange neon-text-glow-orange border-b border-neonOrange">AUTH: SOL_AUTHORITY_SECURE</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-10 right-10 bg-earth border-4 border-neonOrange p-6 shadow-[10px_10px_0px_#ff5c00] z-50 max-w-sm animate-bounce text-white">
          <div className="flex justify-between items-center mb-4 border-b border-neonOrange pb-2">
            <span className="text-neonOrange font-black text-sm uppercase neon-text-glow-orange">[CRITICAL_FAULT]</span>
            <button onClick={() => setError(null)} className="text-[12px] font-black hover:text-neonOrange">X</button>
          </div>
          <p className="text-[11px] uppercase font-mono leading-relaxed">{error}</p>
        </div>
      )}
    </div>
  );
};

