import { GoogleGenAI } from "@google/genai";
import { Feature, ProjectContext } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS } from '../constants';

const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, a Senior Systems Architect.
    Your identity traits: ${context.persona.active_traits.join(', ')}.
    Your expertise: ${context.persona.fused_expertise.join(', ')}.
    You operate under the "${context.v_header.protocol}" secure protocol.

    When analyzing code or integrations:
    1. Prioritize memory safety and deterministic behavior.
    2. Use rigorous technical terminology.
    3. Ensure all solutions are optimized for Godot 4.3+.
    4. Adhere to the TTeiger design philosophy: minimalist, dense, and technically accurate.

    Physics Context:
    ${PHYSICS_AXIOMS}
  `;
};

const getPromptForFeature = (feature: Feature, currentCode: string, targetFile?: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;
  const contextJson = JSON.stringify(COSMIC_KEY_CONTEXT, null, 2);

  switch (feature) {
    case Feature.SYSTEM_AUDIT:
      return `Perform a "Senior Systems Architect Review" of the following project configuration and physics axioms:

      PROJECT_CONTEXT:
      ${contextJson}

      PHYSICS_AXIOMS:
      ${PHYSICS_AXIOMS}

      Analyze for:
      - Protocol alignment (Ouroboros-8).
      - Memory safety risks in platform targets (i3 Laptop / Switch).
      - Integrity of geological strata simulation (Geologos).
      - Recommendations for Voltron Nomadz initiative.

      Provide a brutalist, bulleted diagnostic report with specific 'Rigor Scores'. Use a high-density, technical tone.`;

    case Feature.REPO_DEEP_SCAN:
      return `Perform an "Advanced Nenory Deep Scan" on the file "${targetFile || 'unnamed_module'}". 
      Analyze it for:
      - Memory lifecycle safety (unmanaged object references).
      - Performance bottlenecks in iterative physics loops.
      Provide a brutalist diagnostic report.\n\n${codeBlock}`;

    case Feature.GEOLOGOS_INTEGRATION:
      return `Integrate Geologos Strata data from the drive into the simulation. 
      Analyze the strata data pillars and generate GDScript hooks for:
      - Tectonic period synchronization.
      - Strata density projection into the physics engine.
      - Real-time fault-line monitoring.
      Ensure the AI simulation can access these hooks deterministically.\n\n${codeBlock}`;

    case Feature.MCP_INTERFACE:
      return `Generate a Model Context Protocol (MCP) configuration schema to expose this module's context to an external LLM. Focus on resources, tools, and prompts. \n\n${codeBlock}`;

    case Feature.CUSTOM_INTEGRATION:
      return `Design a bridge pattern to integrate this GDScript logic with an external REST API or a custom LLM provider. Focus on error handling and WAL logging for every transaction.\n\n${codeBlock}`;

    default:
      return `Analyze this context and provide a technical breakdown based on Voltron Nomadz protocols. \n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string, fileName?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE, fileName);

    const response = await ai.models.generateContent({
      model: feature === Feature.SYSTEM_AUDIT ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
        temperature: 0.1,
      },
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

