                : 'bg-bone/40 border-tan hover:border-earth hover:translate-x-1 grayscale opacity-70 hover:opacity-100 hover:grayscale-0'
            }`}
          >
            <div className="flex justify-between items-start mb-2">
              <h3 className={`text-[11px] font-black uppercase tracking-tighter ${
                selectedFeature === f.id ? 'text-neonOrange neon-text-glow-orange' : 'text-earth'
              }`}>
                {f.title}
              </h3>
              {selectedFeature === f.id && gamepadConnected && (
                <span className="button-prompt">A</span>
              )}
            </div>
            <p className={`text-[9px] leading-tight uppercase font-bold tracking-tight ${
              selectedFeature === f.id ? 'text-earth' : 'text-dust'
            }`}>
              {f.description}
            </p>
            <div className={`absolute bottom-0 left-0 h-1 bg-neonGreen transition-all duration-500 ${selectedFeature === f.id ? 'w-full' : 'w-0 group-hover:w-full'}`}></div>
          </button>
        ))}
      </div>

      <div className="mt-6 pt-6 border-t-2 border-earth space-y-4">
        <div key={flipKey} className="book-flip bg-white border-2 border-neonGreen p-4 text-[9px] font-black uppercase shadow-neon-green">
           <div className="text-dust mb-1">SELECTED_BUFFER:</div>
           <div className="text-neonGreen text-[11px] tracking-widest">{selectedFeature}</div>
        </div>

        <button
          onClick={onGenerate}
          disabled={isLoading}
          className="w-full bg-earth text-bone font-black py-5 px-4 hover:bg-neonOrange hover:text-white transition-all active:scale-95 disabled:opacity-30 uppercase text-[14px] tracking-[0.2em] flex items-center justify-center gap-3 shadow-[4px_4px_0px_#ff5c00]"
        >
          {isLoading ? (
            <>
              <div className="w-4 h-4 border-4 border-white border-t-transparent animate-spin"></div>
              CALCULATING...
            </>
          ) : (
            <>
               {gamepadConnected && <span className="button-prompt border-bone text-bone">A</span>}
               START_REALM_SCAN
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default ControlPanel;

import React, { useState, useEffect, useRef } from 'react';
import { MotherBrainAsset } from '../types';
import { MOTHER_BRAIN_ASSETS } from '../constants';

interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
  index: number;
  scrollOffset: number;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId, index, scrollOffset }) => {
  const [isOpen, setIsOpen] = useState(level < 1 || asset.id === 'ai-core-yellow');
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.id === 'ai-core-yellow') return '📂';
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      case 'image_asset': return '🖼️';
      case 'data_pillar': return '🏛️';
      default: return '📄';
    }
  };

  const handleClick = () => {
    if (hasChildren) {
      setIsOpen(!isOpen);
    } else {
      onSelect(asset);
    }
  };

  const style = asset.color && asset.type === 'folder' 
    ? { borderLeft: `4px solid ${asset.color}`, color: asset.color } 
    : {};

  // Rolodex Cylindrical Calculation
  const anglePerItem = 20;
  const rotation = (index * anglePerItem) - (scrollOffset * anglePerItem);
  const opacity = Math.max(0, 1 - Math.abs(rotation) / 90);
  const z = Math.abs(rotation) > 90 ? -500 : Math.cos(rotation * Math.PI / 180) * 50;

  return (
    <div 
      className={`rololodex-item font-mono text-[9px] select-none transition-all duration-300`}
      style={{
        transform: `rotateX(${rotation}deg) translateZ(${z}px)`,
        opacity: opacity,
        pointerEvents: opacity < 0.2 ? 'none' : 'auto'
      }}
    >
      <div 
        className={`flex items-center gap-2 py-1 px-2 cursor-pointer transition-all border-l-2 ${
          isSelected 
            ? 'bg-neonOrange/20 border-neonOrange text-earth shadow-neon-orange scale-105 z-20' 
            : 'border-transparent text-dust hover:bg-bone hover:border-tan hover:text-earth'
        }`}
        style={{ paddingLeft: `${level * 10 + 8}px`, ...style }}
        onClick={handleClick}
      >
        <span className={`opacity-80`}>{getIcon()}</span>
        <span className={`truncate ${asset.id === 'ai-core-yellow' ? 'font-black tracking-widest uppercase' : ''} ${isSelected ? 'font-black text-neonOrange' : ''}`}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-tan/30 ml-3">
          {asset.children!.map((child, i) => (
            <AssetNode key={child.id} asset={child} level={level + 1} onSelect={onSelect} selectedId={selectedId} index={index + i + 1} scrollOffset={scrollOffset} />
          ))}
        </div>
      )}
    </div>
  );
};

interface MotherBrainRepoProps {
  onSelectAsset: (asset: MotherBrainAsset) => void;
  selectedAssetId?: string;
}

const MotherBrainRepo: React.FC<MotherBrainRepoProps> = ({ onSelectAsset, selectedAssetId }) => {
  const [scrollOffset, setScrollOffset] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleWheel = (e: React.WheelEvent) => {
    setScrollOffset(prev => prev + e.deltaY / 100);
  };

  // Flatten assets for easier rolodex indexing
  const flatten = (assets: MotherBrainAsset[]): MotherBrainAsset[] => {
    let res: MotherBrainAsset[] = [];
    assets.forEach(a => {
      res.push(a);
      // We don't fully flatten for now to keep the tree structure, but this is used for base level rolodex
    });
    return res;
  };

  return (
    <div 
      className="bg-cream border-2 border-tan flex flex-col h-full overflow-hidden shadow-sm rolodex-container"
      onWheel={handleWheel}
      ref={containerRef}
    >
      <div className="bg-bone px-3 py-1.5 border-b border-tan flex justify-between items-center z-30">
        <h3 className="text-[9px] font-black text-earth uppercase tracking-widest italic">Wormhole_Assets</h3>
        <div className="flex gap-1 items-center">
          <div className="w-1.5 h-1.5 bg-neonGreen animate-pulse"></div>
        </div>
      </div>

      <div className="flex-grow overflow-hidden p-1 flex flex-col justify-center perspective-[1000px] transform-style-3d">
        <div className="space-y-1 py-10">
          {MOTHER_BRAIN_ASSETS.map((asset, i) => (
            <AssetNode 
              key={asset.id} 
              asset={asset} 
              level={0} 
              onSelect={onSelectAsset} 
              selectedId={selectedAssetId} 
              index={i} 
              scrollOffset={scrollOffset}
            />
          ))}
        </div>
      </div>

      <div className="p-2 bg-bone/40 border-t border-tan text-[7px] font-bold text-dust uppercase flex justify-between z-30">
        <span>ROLODEX_v3</span>
        <span className="text-neonOrange italic">POS: {scrollOffset.toFixed(1)}</span>
      </div>
    </div>
  );
};

export default MotherBrainRepo;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT } from './constants';
import { Feature, CameraSettings, MotherBrainAsset } from './types';
import { generateContent } from './services/geminiService';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.SYSTEM_AUDIT);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [videoUrl, setVideoUrl] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [theme, setTheme] = useState<'bone' | 'void' | 'brutalist' | 'yellow'>('bone');
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [gamepadConnected, setGamepadConnected] = useState(false);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const lastProcessedRef = useRef(0);

  // Define handlers before useEffect to avoid "used before its declaration" error.
  const handleOpenApiKey = async () => {
    // @ts-ignore
    await window.aistudio.openSelectKey();
    setRequiresApiKey(false);
  };

  const handleGenerateVideo = async () => {
    setIsLoading(true);
    setVideoUrl(undefined);
    setOutput('');
    setLoadingStatus('RE-INITIALIZING_VEO_PIPELINE');

    try {
      // @ts-ignore
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) {
        setRequiresApiKey(true);
        setIsLoading(false);
        return;
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      setLoadingStatus('SYNTHESIZING_ORBITAL_V-MOTION');

      const promptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create a brutalist retro-sci-fi video prompt. Colors: Bone background, Neon Orange accents. Subject: Orbital physics simulation lines.`,
        config: { systemInstruction: "Output only the prompt string." }
      });

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: promptResponse.text || "16-bit planetary orbits spinning.",
        config: { numberOfVideos: 1, resolution: '1080p', aspectRatio: '16:9' }
      });

      while (!operation.done) {
        setLoadingStatus(`V-MOTION_PHASE_${Math.floor(Math.random() * 999)}`);
        await new Promise(resolve => setTimeout(resolve, 8000));
        operation = await ai.operations.getVideosOperation({ operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  };

  const handleGenerate = useCallback(async () => {
    if (selectedFeature === Feature.VIDEO_GENERATION) {
      handleGenerateVideo();
      return;
    }

    setIsLoading(true);
    setVideoUrl(undefined);
    setRequiresApiKey(false);
    setError(null);
    setLoadingStatus(selectedFeature === Feature.SYSTEM_AUDIT ? 'AUDITING_PROTOCOL_HANDSHAKE' : 'SCANNING_REPO_STRATA');

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;
    const targetName = selectedAsset?.name || 'buffer.gd';

    const result = await generateContent(selectedFeature, targetCode, targetName);
    setOutput(result);
    setIsLoading(false);
    setLoadingStatus(undefined);
  }, [selectedFeature, selectedAsset]);

  // Controller Polling Loop for Switch Pro / General Gamepads
  useEffect(() => {
    const pollGamepad = () => {
      const gamepads = navigator.getGamepads();
      const gp = gamepads[0]; // Assuming primary controller
      if (gp) {
        setGamepadConnected(true);
        const now = Date.now();
        if (now - lastProcessedRef.current < 200) { 
          requestAnimationFrame(pollGamepad);
          return;
        }

        // Feature Navigation (Vertical)
        // D-Pad Up (12), Down (13) or Left Stick Y (Axis 1)
        const vertical = gp.axes[1] || (gp.buttons[12].pressed ? -1 : gp.buttons[13].pressed ? 1 : 0);
        if (Math.abs(vertical) > 0.5) {
          const currentIndex = FEATURES.findIndex(f => f.id === selectedFeature);
          if (vertical > 0.5) { // Down
            const next = (currentIndex + 1) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
          } else { // Up
            const next = (currentIndex - 1 + FEATURES.length) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
          }
          lastProcessedRef.current = now;
        }

        // Action Trigger
        // Switch Pro 'A' is usually Button 1, 'B' is Button 0
        if (gp.buttons[1].pressed) { // A button: Execute
          handleGenerate();
          lastProcessedRef.current = now;
        }

        if (gp.buttons[0].pressed) { // B button: Reset/Clear
          setOutput('');
          setVideoUrl(undefined);
          lastProcessedRef.current = now;
        }

        // Theme Switch (L/R Bumpers)
        if (gp.buttons[4].pressed) { // L
          setTheme('bone');
          lastProcessedRef.current = now;
        }
        if (gp.buttons[5].pressed) { // R
          setTheme('void');
          lastProcessedRef.current = now;
        }
      } else {
        setGamepadConnected(false);
      }
      requestAnimationFrame(pollGamepad);
    };

    const loop = requestAnimationFrame(pollGamepad);
    return () => cancelAnimationFrame(loop);
  }, [selectedFeature, handleGenerate]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);

  return (
    <div className="h-full flex flex-col p-6 gap-6 bg-bone text-earth selection:bg-neonOrange selection:text-white transition-colors duration-500 overflow-hidden">
      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-[4px_4px_0px_#ff5c00] border-2 border-neonOrange">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange">&lt;V&gt;</span>
          </div>
          <div className="flex flex-col">
            <h1 className="text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-neonOrange neon-text-glow-orange italic text-sm tracking-widest">V3.5_NOMADZ</span>
            </h1>
            <p className="text-[10px] font-black uppercase text-dust">HANDSHAKE: <span className="text-neonGreen neon-text-glow-green">{COSMIC_KEY_CONTEXT.persona.identity}</span></p>
          </div>
        </div>

        <div className="flex items-center gap-8">
          {gamepadConnected && (
            <div className="flex items-center gap-2 bg-neonGreen/10 border border-neonGreen px-2 py-1">
              <span className="button-prompt bg-neonGreen text-black border-none shadow-none">P</span>
              <span className="text-[8px] font-black text-neonGreen uppercase tracking-widest">SWITCH_PRO_ACTIVE</span>
            </div>
          )}
          <div className="flex gap-2">
            {(['bone', 'void', 'brutalist', 'yellow'] as const).map(t => (
              <button key={t} onClick={() => setTheme(t)} className={`w-4 h-4 border-2 ${theme === t ? 'border-neonOrange scale-125' : 'border-tan opacity-50'} transition-all`} />
            ))}
          </div>
          <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-12 gap-8 overflow-hidden">
        {/* Left Col: Vision/Assets */}
        <div className="col-span-2 flex flex-col gap-6 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          <div className="flex-grow overflow-hidden border-2 border-earth">
            <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} />
          </div>
        </div>

        {/* Center: Command */}
        <div className="col-span-3 h-full overflow-hidden">
          {selectedFeature === Feature.CUSTOM_INTEGRATION || selectedFeature === Feature.MCP_INTERFACE ? (
            <IntegrationHub />
          ) : (
            <ControlPanel
              features={FEATURES}
              selectedFeature={selectedFeature}
              onSelectFeature={setSelectedFeature}
              onGenerate={handleGenerate}
              isLoading={isLoading}
              gamepadConnected={gamepadConnected}
            />
          )}
        </div>

        {/* Right: Output */}
        <div className="col-span-7 flex flex-col gap-8 overflow-hidden">
          <div className="h-1/2 overflow-hidden">
            {selectedAsset?.type === 'image_asset' ? (
              <div className="h-full bg-earth/10 border-2 border-tan flex items-center justify-center relative overflow-hidden group">
                <div className="absolute inset-0 brutalist-grid opacity-20"></div>
                <div className="text-center z-10 transition-transform group-hover:scale-110 duration-500">
                   <div className="text-5xl mb-4 drop-shadow-lg">🖼️</div>
                   <p className="text-[10px] font-black uppercase text-earth tracking-widest">{selectedAsset.name}</p>
                </div>
              </div>
            ) : selectedAsset?.type === 'data_pillar' ? (
              <div className="h-full bg-safetyYellow/5 border-2 border-safetyYellow flex items-center justify-center relative overflow-hidden group">
                <div className="text-center z-10">
                   <div className="text-5xl mb-4 animate-bounce">🏛️</div>
                   <p className="text-[10px] font-black uppercase text-earth tracking-widest">{selectedAsset.name}</p>
                </div>
              </div>
            ) : (
              <CodeEditor code={selectedAsset?.code || GD_SCRIPT_CODE} fileName={selectedAsset?.name} />
            )}
          </div>
          <div className="h-1/2 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedAsset?.type === 'image_asset' ? 'AI_CORE_VIZ' : (selectedFeatureInfo?.title || 'Execution_Buffer')}
              videoUrl={videoUrl}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
              isImageSelected={selectedAsset?.type === 'image_asset'}
              selectedImageName={selectedAsset?.name}
              isGeologosActive={selectedFeature === Feature.GEOLOGOS_INTEGRATION || selectedAsset?.type === 'data_pillar'}
              isSystemAudit={selectedFeature === Feature.SYSTEM_AUDIT}
            />
          </div>
        </div>
      </main>

      <footer className="shrink-0 flex justify-between items-center text-[10px] font-black uppercase text-dust border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonGreen"></div> PROTOCOL: OUROBOROS_SECURE_V3</span>
          <span className="flex items-center gap-2"><div className="w-2 h-2 bg-neonOrange"></div> RIGOR_SCAN: L4_RIGOROUS</span>
        </div>
        <div className="flex gap-8 italic">
          <span>{new Date().toLocaleTimeString()} (Z)</span>
          <span className="text-neonOrange neon-text-glow-orange border-b border-neonOrange">AUTH: SOL_AUTHORITY_SECURE</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-10 right-10 bg-earth border-4 border-neonOrange p-6 shadow-[10px_10px_0px_#ff5c00] z-50 max-w-sm animate-bounce text-white">
          <div className="flex justify-between items-center mb-4 border-b border-neonOrange pb-2">
            <span className="text-neonOrange font-black text-sm uppercase neon-text-glow-orange">[CRITICAL_FAULT]</span>
            <button onClick={() => setError(null)} className="text-[12px] font-black hover:text-neonOrange">X</button>
          </div>
          <p className="text-[11px] uppercase font-mono leading-relaxed">{error}</p>
        </div>
      )}
    </div>
  );
};

