                 <span className="text-[8px] font-black uppercase opacity-60">Ability_Origin</span>
                 <span className="text-[12px] font-black italic uppercase">Voxel_Recall</span>
              </div>
              <div className="bg-neonOrange text-white p-3 flex flex-col justify-between h-24">
                 <span className="text-[8px] font-black uppercase opacity-60">Ability_Origin</span>
                 <span className="text-[12px] font-black italic uppercase">Kinetic_Blink</span>
              </div>
           </div>
        </div>
        <div className="mt-4 pt-4 border-t-2 border-tan flex justify-between items-center">
           <span className="text-[9px] font-black text-earth/40">SKYRIM_DEPTH_PROTOCOL_v8</span>
           <div className="flex gap-1">
              {[1,2,3,4,5].map(i => <div key={i} className="w-1.5 h-1.5 bg-earth"></div>)}
           </div>
        </div>
      </div>
    );
  };

  const renderContent = () => {
    if (requiresApiKey) {
      return (
        <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-bone/20 shadow-neon-orange">
          <div className="text-5xl mb-4 animate-pulse">🔒</div>
          <h3 className="text-[12px] font-black uppercase text-neonOrange mb-2 tracking-[0.2em]">AUTH_REQUIRED: L5_CRYPT</h3>
          <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Link</button>
        </div>
      );
    }

    if (isLoading) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-tan relative overflow-hidden mb-6 shadow-neon-orange">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">SYNTHESIZING_REALM_DATA</p>
        </div>
      );
    }

    if (featureTitle.includes('Voxel') || isGeologosActive) return renderVoxelStrata();
    if (featureTitle.includes('Audit') || featureTitle.includes('Lore')) return renderLoreVault();

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
          <div className="text-6xl font-black text-dust mb-4 rotate-12">⎔</div>
          <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">Nenory_Standby_Mode</p>
