          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-neonOrange/20 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-tan h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_#332d2911]">
      <div className="px-4 py-2 bg-earth border-b-2 border-neonOrange flex justify-between items-center z-20 shrink-0">
