  return (
    <div 
      className="bg-cream border-2 border-tan flex flex-col h-full overflow-hidden shadow-sm rolodex-container"
      onWheel={handleWheel}
      ref={containerRef}
    >
      <div className="bg-bone px-3 py-1.5 border-b border-tan flex justify-between items-center z-30">
        <h3 className="text-[9px] font-black text-earth uppercase tracking-widest italic">Wormhole_Assets</h3>
        <div className="flex gap-1 items-center">
          <div className="w-1.5 h-1.5 bg-neonGreen animate-pulse"></div>
        </div>
      </div>

      <div className="flex-grow overflow-hidden p-1 flex flex-col justify-center perspective-[1000px] transform-style-3d">
        <div className="space-y-1 py-10">
          {MOTHER_BRAIN_ASSETS.map((asset, i) => (
            <AssetNode 
