const getPromptForFeature = (feature: Feature, currentCode: string, targetFile?: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.VOXEL_STRATA_MAPPING:
      return `Implement a Dual Contouring mesh generator. 
      It must allow for real-time destruction (voxel-style) but maintain smooth, high-fidelity surfaces.
      Integrate with Godot 4.3 VoxelTools. Show logic for 'Explosive Deformation'.\n\n${codeBlock}`;

    case Feature.CYBER_KINETIC_MOVEMENT:
      return `Tune the movement kernel for "Badass Cyberpunk" feel.
      1. First Person: High-speed, head-bob, mantling, and dash-mechanics.
      2. Third Person: Xenoverse-style flight and TOTK-style 'Recall/Fuse' abilities.
      Ensure smooth transitions between perspectives. Provide GDScript updates.\n\n${codeBlock}`;

    case Feature.COMBAT_ORCHESTRATION:
      return `Implement the Combat Kernel for Godot 4.3.
      Includes: Hand-to-hand hit-box logic, Proton Blade (Light Saber) parry systems, and Skyrim-style spell casting (Fire, Ice, Void).
      Handle destructive voxel impacts for melee strikes.\n\n${codeBlock}`;

    case Feature.MECH_SYNTHESIS_L4:
      return `Design the Exoskeleton and Mecha architecture.
      1. Power Suit: Metroid-style Samus armor with upgrade slots.
      2. Titan Mech: Stomping physics, pilot injection logic, and arm-mounted voxel-cannons.
      Include Switch performance notes (low memory impact).\n\n${codeBlock}`;

    case Feature.HOVER_SURF_CALIBRATION:
      return `Silver Surfer style board movement logic.
      Must handle seamless transitions from ground hovering to space-flight.
      Implement "Flow-State" speed boost mechanics and voxel-wave surfing.\n\n${codeBlock}`;

    case Feature.SYSTEM_AUDIT:
      return `Perform a "Master Architecture Review" on the destructive voxel universe.
      Analyze for memory safety on i3 Laptop/Switch targets while maintaining 10^12 world proceduralism.
      Check for Lore-consistency within the Strata Pillars.`;

    default:
      return `Analyze the current Nomadz module for VCN-3.0 compatibility.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string, fileName?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE, fileName);

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
        temperature: 0.2,
      },
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

