    if (featureTitle.includes('Voxel') || isGeologosActive) return renderVoxelStrata();
    if (featureTitle.includes('Audit') || featureTitle.includes('Lore')) return renderLoreVault();

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
          <div className="text-6xl font-black text-dust mb-4 rotate-12">⎔</div>
          <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">Nenory_Standby_Mode</p>
        </div>
      );
    }

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-tan/20 custom-scrollbar overflow-auto">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-neonOrange/20 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-tan h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_#332d2911]">
      <div className="px-4 py-2 bg-earth border-b-2 border-neonOrange flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-bone uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-neonGreen text-[9px] font-black">STABLE_OS</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
    </div>
  );
};

export default OutputDisplay;

import React, { useState, useEffect, useRef } from 'react';
import { MotherBrainAsset } from '../types';
import { MOTHER_BRAIN_ASSETS } from '../constants';

interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
  index: number;
  scrollOffset: number;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId, index, scrollOffset }) => {
  const [isOpen, setIsOpen] = useState(level < 1 || asset.id === 'ai-core-yellow');
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.id === 'ai-core-yellow') return '📂';
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      case 'image_asset': return '🖼️';
      case 'data_pillar': return '🏛️';
      default: return '📄';
    }
  };

  const handleClick = () => {
    if (hasChildren) {
      setIsOpen(!isOpen);
    } else {
      onSelect(asset);
    }
  };

  const style = asset.color && asset.type === 'folder' 
    ? { borderLeft: `4px solid ${asset.color}`, color: asset.color } 
    : {};

  const anglePerItem = 20;
  const rotation = (index * anglePerItem) - (scrollOffset * anglePerItem);
  const opacity = Math.max(0, 1 - Math.abs(rotation) / 90);
  const z = Math.abs(rotation) > 90 ? -500 : Math.cos(rotation * Math.PI / 180) * 50;

  return (
    <div 
      className={`rolodex-item font-mono text-[9px] select-none transition-all duration-300 group`}
      style={{
        transform: `rotateX(${rotation}deg) translateZ(${z}px)`,
        opacity: opacity,
        pointerEvents: opacity < 0.2 ? 'none' : 'auto'
      }}
    >
      <div 
        className={`flex items-center gap-2 py-1 px-2 cursor-pointer transition-all border-l-2 ${
          isSelected 
            ? 'bg-neonOrange/20 border-neonOrange text-earth shadow-neon-orange scale-105 z-20' 
            : 'border-transparent text-dust hover:bg-bone hover:border-neonOrange hover:text-neonOrange hover:scale-105 hover:z-10 shadow-none hover:shadow-neon-orange/20'
        }`}
        style={{ paddingLeft: `${level * 10 + 8}px`, ...style }}
        onClick={handleClick}
      >
        <span className={`opacity-80 transition-transform group-hover:scale-110`}>{getIcon()}</span>
        <span className={`truncate transition-all ${asset.id === 'ai-core-yellow' ? 'font-black tracking-widest uppercase' : ''} ${isSelected ? 'font-black text-neonOrange' : 'group-hover:font-bold'}`}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-tan/30 ml-3">
          {asset.children!.map((child, i) => (
            <AssetNode key={child.id} asset={child} level={level + 1} onSelect={onSelect} selectedId={selectedId} index={index + i + 1} scrollOffset={scrollOffset} />
          ))}
        </div>
      )}
    </div>
  );
};

interface MotherBrainRepoProps {
  onSelectAsset: (asset: MotherBrainAsset) => void;
  selectedAssetId?: string;
}

const MotherBrainRepo: React.FC<MotherBrainRepoProps> = ({ onSelectAsset, selectedAssetId }) => {
  const [scrollOffset, setScrollOffset] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleWheel = (e: React.WheelEvent) => {
    setScrollOffset(prev => prev + e.deltaY / 100);
  };

  return (
    <div 
      className="bg-cream border-2 border-tan flex flex-col h-full overflow-hidden shadow-sm rolodex-container"
      onWheel={handleWheel}
      ref={containerRef}
    >
      <div className="bg-bone px-3 py-1.5 border-b border-tan flex justify-between items-center z-30">
        <h3 className="text-[9px] font-black text-earth uppercase tracking-widest italic">Wormhole_Assets</h3>
        <div className="flex gap-1 items-center">
          <div className="w-1.5 h-1.5 bg-neonGreen animate-pulse"></div>
        </div>
      </div>

      <div className="flex-grow overflow-hidden p-1 flex flex-col justify-center perspective-[1000px] transform-style-3d">
        <div className="space-y-1 py-10">
          {MOTHER_BRAIN_ASSETS.map((asset, i) => (
            <AssetNode 
              key={asset.id} 
              asset={asset} 
              level={0} 
              onSelect={onSelectAsset} 
              selectedId={selectedAssetId} 
              index={i} 
              scrollOffset={scrollOffset}
            />
          ))}
        </div>
      </div>

      <div className="p-2 bg-bone/40 border-t border-tan text-[7px] font-bold text-dust uppercase flex justify-between z-30">
        <span>ROLODEX_v3</span>
        <span className="text-neonOrange italic">POS: {scrollOffset.toFixed(1)}</span>
      </div>
    </div>
  );
};

export default MotherBrainRepo;
